package com.smartfarm360.service;

import com.smartfarm360.controller.SfFinanceController.*;
import com.smartfarm360.repository.SfTenantMembershipRepository;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal;
import java.util.*;

@Service
public class SfFinanceService {
    private final JdbcTemplate jdbc; private final SfTenantMembershipRepository memberships;
    public SfFinanceService(JdbcTemplate jdbc, SfTenantMembershipRepository memberships) { this.jdbc=jdbc; this.memberships=memberships; }
    private void access(String email, Long tenantId, boolean write) {
        var m=memberships.findByTenantIdAndUserEmailIgnoreCaseAndActiveTrue(tenantId,email)
            .orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Tenant not found"));
        if(write && !List.of("OWNER","ADMIN","FARM_MANAGER").contains(m.getRole())) throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You do not have permission to change finance or inventory data");
    }
    private void validateFarm(Long tenantId, Long farmId) { if(farmId!=null && jdbc.queryForObject("select count(*) from sf_farms where id=? and tenant_id=? and active=true",Integer.class,farmId,tenantId)==0) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Farm does not belong to this tenant"); }
    @Transactional(readOnly=true) public Map<String,Object> summary(String email,Long t){access(email,t,false); Map<String,Object> m=new LinkedHashMap<>();
        m.put("income",jdbc.queryForObject("select coalesce(sum(amount),0) from sf_finance_entries where tenant_id=? and entry_type='INCOME'",BigDecimal.class,t));
        m.put("expenses",jdbc.queryForObject("select coalesce(sum(amount),0) from sf_finance_entries where tenant_id=? and entry_type='EXPENSE'",BigDecimal.class,t));
        m.put("inventoryValue",jdbc.queryForObject("select coalesce(sum(quantity_on_hand*average_unit_cost),0) from sf_inventory_items where tenant_id=? and active=true",BigDecimal.class,t));
        m.put("outstandingPayables",jdbc.queryForObject("select coalesce(sum(total_amount-paid_amount),0) from sf_purchases where tenant_id=?",BigDecimal.class,t));
        m.put("lowStockItems",jdbc.queryForObject("select count(*) from sf_inventory_items where tenant_id=? and active=true and quantity_on_hand<=reorder_level",Integer.class,t));
        BigDecimal paidIncome=jdbc.queryForObject("select coalesce(sum(amount),0) from sf_finance_entries where tenant_id=? and entry_type='INCOME' and payment_status='PAID'",BigDecimal.class,t); BigDecimal paidExpenses=jdbc.queryForObject("select coalesce(sum(amount),0) from sf_finance_entries where tenant_id=? and entry_type='EXPENSE' and payment_status='PAID'",BigDecimal.class,t); m.put("netCashRecorded",paidIncome.subtract(paidExpenses)); return m; }
    @Transactional(readOnly=true) public List<Map<String,Object>> entries(String email,Long t){access(email,t,false);return jdbc.queryForList("select id,tenant_id as \"tenantId\",farm_id as \"farmId\",entry_type as \"entryType\",category,description,amount,occurred_on as \"occurredOn\",payment_status as \"paymentStatus\",reference_no as \"referenceNo\",created_at as \"createdAt\" from sf_finance_entries where tenant_id=? order by occurred_on desc,id desc limit 500",t);}
    @Transactional public Map<String,Object> createEntry(String email,Long t,FinanceRequest r){access(email,t,true);validateFarm(t,r.farmId());String type=r.entryType().trim().toUpperCase(Locale.ROOT);if(!Set.of("INCOME","EXPENSE").contains(type))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"entryType must be INCOME or EXPENSE");String status=r.paymentStatus()==null?"PAID":r.paymentStatus().trim().toUpperCase(Locale.ROOT);if(!Set.of("PAID","UNPAID","PARTIAL").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"paymentStatus must be PAID, UNPAID or PARTIAL");Long id=jdbc.queryForObject("insert into sf_finance_entries(tenant_id,farm_id,entry_type,category,description,amount,occurred_on,payment_status,reference_no,created_by) values(?,?,?,?,?,?,?,?,?,?) returning id",Long.class,t,r.farmId(),type,r.category().trim(),r.description().trim(),r.amount(),r.occurredOn(),status,r.referenceNo(),email);return jdbc.queryForMap("select id,tenant_id as \"tenantId\",farm_id as \"farmId\",entry_type as \"entryType\",category,description,amount,occurred_on as \"occurredOn\",payment_status as \"paymentStatus\",reference_no as \"referenceNo\" from sf_finance_entries where id=? and tenant_id=?",id,t);}
    @Transactional(readOnly=true) public List<Map<String,Object>> suppliers(String email,Long t){access(email,t,false);return jdbc.queryForList("select id,tenant_id as \"tenantId\",name,phone,village,notes,active,created_at as \"createdAt\" from sf_suppliers where tenant_id=? and active=true order by name",t);}
    @Transactional public Map<String,Object> createSupplier(String email,Long t,SupplierRequest r){access(email,t,true);Long id=jdbc.queryForObject("insert into sf_suppliers(tenant_id,name,phone,village,notes) values(?,?,?,?,?) returning id",Long.class,t,r.name().trim(),r.phone(),r.village(),r.notes());return jdbc.queryForMap("select id,tenant_id as \"tenantId\",name,phone,village,notes,active from sf_suppliers where id=? and tenant_id=?",id,t);}
    @Transactional(readOnly=true) public List<Map<String,Object>> items(String email,Long t){access(email,t,false);return jdbc.queryForList("select id,tenant_id as \"tenantId\",name,category,unit,quantity_on_hand as \"quantityOnHand\",reorder_level as \"reorderLevel\",average_unit_cost as \"averageUnitCost\",(quantity_on_hand*average_unit_cost) as \"stockValue\",active from sf_inventory_items where tenant_id=? and active=true order by name",t);}
    @Transactional public Map<String,Object> createItem(String email,Long t,ItemRequest r){access(email,t,true);Long id=jdbc.queryForObject("insert into sf_inventory_items(tenant_id,name,category,unit,quantity_on_hand,reorder_level,average_unit_cost) values(?,?,?,?,?,?,?) returning id",Long.class,t,r.name().trim(),r.category().trim(),r.unit().trim(),r.quantityOnHand(),r.reorderLevel(),r.averageUnitCost());return jdbc.queryForMap("select id,tenant_id as \"tenantId\",name,category,unit,quantity_on_hand as \"quantityOnHand\",reorder_level as \"reorderLevel\",average_unit_cost as \"averageUnitCost\" from sf_inventory_items where id=? and tenant_id=?",id,t);}
    @Transactional(readOnly=true) public List<Map<String,Object>> purchases(String email,Long t){access(email,t,false);return jdbc.queryForList("select p.id,p.supplier_id as \"supplierId\",s.name as \"supplierName\",p.item_id as \"itemId\",i.name as \"itemName\",p.purchase_date as \"purchaseDate\",p.quantity,p.unit_cost as \"unitCost\",p.total_amount as \"totalAmount\",p.paid_amount as \"paidAmount\",(p.total_amount-p.paid_amount) as \"outstandingAmount\",p.notes from sf_purchases p join sf_suppliers s on s.id=p.supplier_id and s.tenant_id=p.tenant_id join sf_inventory_items i on i.id=p.item_id and i.tenant_id=p.tenant_id where p.tenant_id=? order by p.purchase_date desc,p.id desc limit 500",t);}
    @Transactional public Map<String,Object> createPurchase(String email,Long t,PurchaseRequest r){access(email,t,true);if(r.paidAmount().compareTo(r.quantity().multiply(r.unitCost()))>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Paid amount cannot exceed purchase total");
        var supplier=jdbc.queryForList("select id from sf_suppliers where id=? and tenant_id=? and active=true",r.supplierId(),t);if(supplier.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Supplier does not belong to this tenant");
        var rows=jdbc.queryForList("select id,quantity_on_hand,average_unit_cost from sf_inventory_items where id=? and tenant_id=? and active=true for update",r.itemId(),t);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Inventory item does not belong to this tenant");
        BigDecimal total=r.quantity().multiply(r.unitCost());Map<String,Object> item=rows.get(0);BigDecimal oldQty=(BigDecimal)item.get("quantity_on_hand");BigDecimal oldCost=(BigDecimal)item.get("average_unit_cost");BigDecimal newQty=oldQty.add(r.quantity());BigDecimal newAvg=newQty.signum()==0?BigDecimal.ZERO:oldQty.multiply(oldCost).add(r.quantity().multiply(r.unitCost())).divide(newQty,2,java.math.RoundingMode.HALF_UP);
        jdbc.update("update sf_inventory_items set quantity_on_hand=?,average_unit_cost=? where id=? and tenant_id=?",newQty,newAvg,r.itemId(),t);
        Long id=jdbc.queryForObject("insert into sf_purchases(tenant_id,supplier_id,item_id,purchase_date,quantity,unit_cost,total_amount,paid_amount,notes,created_by) values(?,?,?,?,?,?,?,?,?,?) returning id",Long.class,t,r.supplierId(),r.itemId(),r.purchaseDate(),r.quantity(),r.unitCost(),total,r.paidAmount(),r.notes(),email);
        return jdbc.queryForMap("select p.id,p.supplier_id as \"supplierId\",s.name as \"supplierName\",p.item_id as \"itemId\",i.name as \"itemName\",p.purchase_date as \"purchaseDate\",p.quantity,p.unit_cost as \"unitCost\",p.total_amount as \"totalAmount\",p.paid_amount as \"paidAmount\",(p.total_amount-p.paid_amount) as \"outstandingAmount\" from sf_purchases p join sf_suppliers s on s.id=p.supplier_id and s.tenant_id=p.tenant_id join sf_inventory_items i on i.id=p.item_id and i.tenant_id=p.tenant_id where p.id=? and p.tenant_id=?",id,t); }
}
